# =============================================================================
# SEARCH FUNCTIONS
# =============================================================================


def find_nearest_areas(
    lat: float, lon: float, max_distance_km: float = 10.0, limit: int = 20
) -> list[dict]:
    """
    Find fishing areas nearest to a GPS coordinate using Haversine distance.

    Args:
        lat: Latitude of the search point.
        lon: Longitude of the search point.
        max_distance_km: Maximum search radius in kilometers.
        limit: Maximum number of results to return.

    Returns:
        List of area dicts with added "distance_km" field, sorted by distance.
    """
    results = []
    for area in CZECH_AREAS:
        area_lat = area["lat"]
        area_lon = area["lon"]
        if area_lat is None or area_lon is None:
            continue
        dist = _haversine_km(lat, lon, area_lat, area_lon)
        if dist <= max_distance_km:
            results.append({**area, "distance_km": round(dist, 2)})
    results.sort(key=lambda x: x["distance_km"])
    return results[:limit]


def find_area_by_code(code: str) -> Optional[dict]:
    """
    Find an area by its code (with or without space).

    Args:
        code: Area code like "401 001" or "401001".

    Returns:
        Area dict or None if not found.
    """
    code_clean = code.replace(" ", "")
    for area in CZECH_AREAS:
        if area["code_clean"] == code_clean:
            return area
    return None


def search_areas_by_name(query: str, limit: int = 20) -> list[dict]:
    """
    Search areas by name (case-insensitive partial match).

    Args:
        query: Search string.
        limit: Max results.

    Returns:
        List of matching area dicts.
    """
    q = query.lower()
    results = [a for a in CZECH_AREAS if q in a["name"].lower() or q in a["code"]]
    return results[:limit]


def get_areas_by_region(region_code: str) -> list[dict]:
    """
    Get all areas in a region.

    Args:
        region_code: 3-digit region prefix (e.g. "401").

    Returns:
        List of area dicts in that region.
    """
    return [a for a in CZECH_AREAS if a["region_code"] == region_code]

